insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('febab611-d9c1-5d22-a312-f26b33d9348b', 'drill-math-geometry-trig', 'Math: Geometry and Trigonometry', 'Angles, area and volume, right triangles, circles', 'drill', 'math', 'geometry_trig', 'mixed', 'Angle relationships, similar triangles, area and volume, right-triangle trigonometry and circle equations and sectors.', 23) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('4e8c74d2-bc96-56ab-af4f-0c19ce031083', 'febab611-d9c1-5d22-a312-f26b33d9348b', 1, 'Math: Geometry and Trigonometry', 'math', 800) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5ce49bbe-54e6-5790-a1bb-ceaea527c009', '4e8c74d2-bc96-56ab-af4f-0c19ce031083', 1, 'geometry_trig', 'lines_angles_triangles', 'easy', 'mc', null, 'Two angles are supplementary. If one measures 118°, what is the measure of the other?', '[{"key":"A","text":"28°"},{"key":"B","text":"62°"},{"key":"C","text":"72°"},{"key":"D","text":"242°"}]'::jsonb, 'B', null, 'Supplementary angles sum to 180°, so the other is 180 − 118 = 62°. Choice A uses 90° and answers the complementary question instead.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fbcc9d10-92a6-54f0-a313-8c35676cef2c', '4e8c74d2-bc96-56ab-af4f-0c19ce031083', 2, 'geometry_trig', 'area_volume', 'easy', 'spr', null, 'A triangle has a base of 14 cm and a height of 9 cm. What is its area, in square centimetres?', null, '63', '["63.0"]'::jsonb, 'Area is ½ × base × height = ½ × 14 × 9 = 63. Answering 126 omits the factor of one half and gives the area of the enclosing rectangle.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('dc89c9fa-1bc3-537e-a67a-8f209a4e376d', '4e8c74d2-bc96-56ab-af4f-0c19ce031083', 3, 'geometry_trig', 'circles', 'medium', 'mc', null, 'A circle in the xy-plane has equation (x − 3)² + (y + 1)² = 25. What are its centre and radius?', '[{"key":"A","text":"Centre (3, −1), radius 5"},{"key":"B","text":"Centre (−3, 1), radius 5"},{"key":"C","text":"Centre (3, −1), radius 25"},{"key":"D","text":"Centre (−3, 1), radius 25"}]'::jsonb, 'A', null, 'In standard form (x − h)² + (y − k)² = r², the centre is (h, k) and the radius is √25 = 5, so the centre is (3, −1). Choice C reports r² instead of taking its square root.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7a6643db-6fde-5de5-a66c-70e1a210d655', '4e8c74d2-bc96-56ab-af4f-0c19ce031083', 4, 'geometry_trig', 'right_triangles_trig', 'medium', 'mc', null, 'In a right triangle, one leg measures 5 and the hypotenuse measures 13. What is the length of the other leg?', '[{"key":"A","text":"8"},{"key":"B","text":"12"},{"key":"C","text":"14"},{"key":"D","text":"18"}]'::jsonb, 'B', null, 'By the Pythagorean theorem, the missing leg is √(169 − 25) = √144 = 12. Choice A subtracts the side lengths directly instead of their squares.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('28110d2e-56c2-5175-a638-f48ee5131c99', '4e8c74d2-bc96-56ab-af4f-0c19ce031083', 5, 'geometry_trig', 'lines_angles_triangles', 'medium', 'spr', null, 'Triangle ABC is similar to triangle DEF. AB = 6, BC = 9, and DE = 10. What is the length of EF?', null, '15', '["15.0"]'::jsonb, 'The scale factor is 10/6 = 5/3, so EF = 9 × 5/3 = 15. Answering 13 adds the difference of 4 rather than applying the ratio, which similar figures require.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('fd31dc4c-e622-56a9-aebc-dad130ff9cdb', '4e8c74d2-bc96-56ab-af4f-0c19ce031083', 6, 'geometry_trig', 'area_volume', 'hard', 'mc', null, 'A cylinder has radius 4 cm and height 10 cm. If the radius is doubled and the height is unchanged, the volume is multiplied by', '[{"key":"A","text":"2"},{"key":"B","text":"4"},{"key":"C","text":"8"},{"key":"D","text":"10"}]'::jsonb, 'B', null, 'Volume is πr²h, and squaring a doubled radius multiplies the volume by 2² = 4. Choice A applies the doubling directly, ignoring that the radius is squared in the formula.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('40f6d524-99a9-5131-a07b-2328ea4c254d', '4e8c74d2-bc96-56ab-af4f-0c19ce031083', 7, 'geometry_trig', 'right_triangles_trig', 'hard', 'mc', null, 'In right triangle PQR, angle R = 90° and tan P = 3/4. What is the value of sin P?', '[{"key":"A","text":"3/5"},{"key":"B","text":"4/5"},{"key":"C","text":"3/4"},{"key":"D","text":"5/3"}]'::jsonb, 'A', null, 'A tangent of 3/4 gives legs of 3 and 4 and a hypotenuse of 5, so sin P = opposite/hypotenuse = 3/5. Choice B is cos P, using the adjacent leg instead.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('49a43d34-cc75-58b1-a2f2-f3c87ed24f12', '4e8c74d2-bc96-56ab-af4f-0c19ce031083', 8, 'geometry_trig', 'circles', 'hard', 'spr', null, 'A sector of a circle of radius 6 has an area of 12π. What is the measure of its central angle, in degrees?', null, '120', '["120.0"]'::jsonb, 'The full circle has area 36π, so the sector is 12π/36π = 1/3 of it, and one third of 360° is 120°. Answering 60 comes from comparing the sector to a semicircle rather than to the whole circle.') on conflict (id) do nothing;
